entries[1248523] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nOuroboric Curse\nWhen any player's health falls below 50 %, the curse awakens, Horrifying nearby enemies for 6 sec while granting them 20 % increased primary and 50 % increased leech, avoidance, and speed for 20 sec. This effect can only occur once every 2 min.\n\nUse: Add this Curio to your companion's collection." }
