entries[1248525] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nOuroboric Curse\nWhen any player's health falls below 50 %, the curse awakens, Horrifying nearby enemies for 6 sec while granting them 25 % increased primary and 75 % increased leech, avoidance, and speed for 20 sec. This effect can only occur once every 2 min.\n\nKilling Poisoned enemies reduces this effect's cooldown by 6 sec.\n\nUse: Add this Curio to your companion's collection." }
